/**
 * Panel kinds: what the shell can open. A kind is a React component plus its default params; the shell
 * keeps each panel's params in the layout (so a saved workspace restores them) and gives the component a
 * setter. Params must be JSON: they are saved as they are.
 *
 *   export const quotesPanel = definePanel({
 *     kind: 'quotes', title: 'Quotes', defaultParams: { table: 'quotes' },
 *     component: ({ params, setParams, linkGroup }) => ...,
 *   });
 *   <Shell kinds={[chartPanel, tablePanel, quotesPanel]} />
 */
import type { ComponentType } from 'react';

export interface PanelProps<P extends object = Record<string, unknown>> {
  /** the panel's id in the layout */
  id: string;
  params: P;
  /** merge into the params (saved with the workspace) */
  setParams(patch: Partial<P>): void;
  setTitle(title: string): void;
  /** the link group this panel is in (null: not linked); the user picks it in the panel's header */
  linkGroup: string | null;
  /**
   * Open another panel: by default a floating window the user can close or drag into the layout; `where` docks it
   * instead (`docked`, placed relative to this or another panel; `within` adds a tab to its group). Returns the new
   * panel's id (null if the kind is unknown).
   */
  openPanel(kind: string, params?: Record<string, unknown>, title?: string, where?: PanelPlacement): string | null;
}

export interface PanelPlacement {
  /** dock it into the layout, placed by referencePanel and direction (default: a floating window) */
  docked?: boolean;
  /** the panel to place it next to (default: the one opening it) */
  referencePanel?: string;
  direction?: 'right' | 'left' | 'above' | 'below' | 'within';
  /** the floating window's share of the shell's size (default 0.6) */
  floating?: number;
}

export interface PanelKind<P extends object = any> {
  kind: string;
  /** the tab's title for a new panel */
  title: string | ((params: P) => string);
  component: ComponentType<PanelProps<P>>;
  defaultParams?: P;
  /** the name in the "add panel" menu (default: the title) */
  label?: string;
  /**
   * Put before the tab's title (e.g. 'T:' for a table): says what kind of panel shows a picked result, for kinds
   * whose title is otherwise just the thing picked (a table's name)
   */
  titlePrefix?: string;
  /** a line for the "add panel" menu */
  description?: string;
  /** whether the header shows a link-group picker (default true) */
  linkable?: boolean;
  /** the link group a new panel starts in (default 'red'; null: unlinked) */
  defaultLink?: string | null;
}

export function definePanel<P extends object>(kind: PanelKind<P>): PanelKind<P> {
  return kind;
}

/** The params the shell stores: the kind's own, plus the panel's link group. */
export type StoredParams = Record<string, unknown> & {
  __link?: string | null;
  /** read from another engine (a run's), not the page's own: see engines.tsx */
  __engine?: { run: number } | null;
};

export function titleOf(kind: PanelKind, params: object): string {
  return withPrefix(kind, typeof kind.title === 'function' ? kind.title(params) : kind.title);
}

/** `title` with the kind's prefix (once). */
export function withPrefix(kind: PanelKind, title: string): string {
  const pre = kind.titlePrefix;
  return pre && !title.startsWith(pre) ? `${pre} ${title}` : title;
}
