/**
 * Symbols and their datasets. A symbol is the persistent identity of something (a bond, a future, a trading book,
 * an order, an RFQ); a dataset is one view of it (a bond's price, yield and idio; a book's positions and
 * executions), which may be chartable, tabulatable, or both. Indicators are transforms over a dataset (a dataset
 * may start as an indicator and be promoted to a dataset of its own).
 *
 * The link bus carries symbols only; each panel picks which of the symbol's datasets it shows (the chart: its
 * chartable ones, the table panel in symbol mode: its tabulatable ones). An app describes its symbols once:
 *
 *   <SymbolModelProvider model={{ useSymbols, useDatasets, resolve }}> <Shell ... /> </SymbolModelProvider>
 */
import { createContext, createElement, useContext, type ReactNode } from 'react';

export interface SymbolInfo {
  sym: string;
  /** what kind of thing it is: bond, future, book, ... */
  kind: string;
  name: string;
  /** a heading to list it under */
  group?: string;
}

export interface DatasetDef {
  key: string;
  label: string;
  description?: string;
  /** chartable: the chart API symbol (or expression) that charts it */
  chart?: string;
  /** tabulatable: a published table, the filters that pick this symbol's rows, the column a row click links */
  table?: { table: string; where?: Record<string, string>; linkColumn?: string };
}

export interface SymbolModel {
  /** every symbol (a hook: it may fetch them); null while loading */
  useSymbols(): SymbolInfo[] | null;
  /** a symbol's datasets (a hook), chartable first */
  useDatasets(sym: string): DatasetDef[];
  /** a name that stands for a symbol's dataset (a series' own chart symbol, e.g. 'X.IDIO') -> that symbol and dataset */
  resolve?(name: string): { sym: string; dataset: string } | null;
}

const NONE: SymbolModel = { useSymbols: () => null, useDatasets: () => [] };
const Ctx = createContext<SymbolModel>(NONE);

export function SymbolModelProvider({ model, children }: { model: SymbolModel; children?: ReactNode }) {
  return createElement(Ctx.Provider, { value: model }, children);
}

/** The app's symbol model (one that knows nothing when none is provided). */
export function useSymbolModel(): SymbolModel {
  return useContext(Ctx);
}

/** A symbol's datasets from the app's model. */
export function useDatasets(sym: string): DatasetDef[] {
  return useContext(Ctx).useDatasets(sym);
}
